import { createWatchdog, iterateWithIdleTimeout } from "../src/utils/idle-iterator";

// One past the 32-bit setTimeout limit (about 24.9 days); setTimeout would treat it as 1 ms.
const BEYOND_TIMER_LIMIT_MS = 2 ** 31;

describe("idle watchdogs beyond the setTimeout limit", () => {
	it("does not abort a slow stream when the idle and first-item timeouts are very long", async () => {
		// Given a stream that pauses 50 ms between items.
		async function* slow(): AsyncGenerator<number> {
			yield 1;
			await Bun.sleep(50);
			yield 2;
		}

		// When it is read with idle and first-item timeouts past the timer limit.
		const items: number[] = [];
		for await (const item of iterateWithIdleTimeout(slow(), {
			idleTimeoutMs: BEYOND_TIMER_LIMIT_MS,
			firstItemTimeoutMs: BEYOND_TIMER_LIMIT_MS,
			errorMessage: "idle timeout",
		})) {
			items.push(item);
		}

		// Then every item arrives instead of an immediate idle timeout.
		expect(items).toEqual([1, 2]);
	});

	it("does not fire a first-event watchdog with a very long timeout right away", async () => {
		let fired = false;
		const watchdog = createWatchdog(BEYOND_TIMER_LIMIT_MS, () => {
			fired = true;
		});
		try {
			await Bun.sleep(30);
		} finally {
			if (watchdog) clearTimeout(watchdog);
		}
		expect(fired).toBe(false);
	});
});

import * as fs from "node:fs";

import * as logger from "../src/logger";
import * as postmortem from "../src/postmortem";

logger.setTransports({ console: true, file: false });

type ExitListener = (code?: number) => unknown;

interface EpipeDetails {
	fd?: number;
	syscall?: string;
}

function getPostmortemExitListener(): ExitListener {
	const listener = process.rawListeners("exit").at(-1);
	if (!listener) {
		throw new Error("postmortem exit listener was not registered");
	}
	return listener as ExitListener;
}

function writeResult(result: Record<string, unknown>): void {
	process.stdout.write(`${JSON.stringify(result)}\n`);
}

function epipeError(message: string, details: EpipeDetails): Error {
	return Object.assign(new Error(message), { code: "EPIPE", ...details });
}
/**
 * Construct a peer-closed error with an arbitrary code, for EIO/EBADF
 * regression fixtures that exercise the broader closed-stdout family.
 */
function closedFdError(message: string, code: string, details: EpipeDetails): Error {
	return Object.assign(new Error(message), { code, ...details });
}

async function throwFromTimer(error: Error): Promise<void> {
	setTimeout(() => {
		throw error;
	}, 10);
	await Bun.sleep(2_000);
}

function writeUntilStdoutPipeBreaks(): void {
	for (let i = 0; i < 256; i++) {
		process.stdout.write(`${"x".repeat(8192)}\n`);
	}
}

async function runExitReentryWhileRunning(): Promise<void> {
	let count = 0;
	const exitListener = getPostmortemExitListener();
	postmortem.register("fixture-exit-reentry", async () => {
		count++;
		await Promise.resolve(exitListener(0));
	});

	await postmortem.cleanup();
	await Bun.sleep(20);
	writeResult({ count });
}

async function runNonExitRecursiveCleanup(): Promise<void> {
	let count = 0;
	postmortem.register("fixture-non-exit-recursion", async () => {
		count++;
		await postmortem.cleanup();
	});

	await postmortem.cleanup();
	await Bun.sleep(20);
	writeResult({ count });
}

async function runQuitReentryWaitsForCleanup(): Promise<void> {
	let count = 0;
	let cleanupFinished = false;
	let exitBeforeCleanupFinished = false;
	const originalExit = process.exit;
	process.exit = (() => {
		exitBeforeCleanupFinished = !cleanupFinished;
	}) as typeof process.exit;

	try {
		postmortem.register("fixture-quit-reentry-slow", async () => {
			count++;
			await Bun.sleep(20);
			cleanupFinished = true;
		});
	await Bun.sleep(2_000);
}

async function runConsecutiveSignalsShareCleanup(): Promise<void> {
	let count = 0;
	postmortem.register("fixture-consecutive-signals", async reason => {
		count++;
		await Bun.sleep(500);
		writeResult({ count, reason });
	});

	setTimeout(() => process.kill(process.pid, "SIGTERM"), 20);
	process.kill(process.pid, "SIGHUP");
	await Bun.sleep(5_000);
}

async function runCleanupDeadlineSignal(): Promise<void> {
	process.env.GJC_CLEANUP_DEADLINE_MS = "300";
	postmortem.register("fixture-deadline-signal", async () => {
		writeResult({ started: true });
		await new Promise(() => {});
	});

	process.kill(process.pid, "SIGTERM");
	await Bun.sleep(10_000);
}

async function runCleanupDeadlineQuit(): Promise<void> {
	process.env.GJC_CLEANUP_DEADLINE_MS = "300";
	postmortem.register("fixture-deadline-quit", async () => {
		writeResult({ started: true });
		await new Promise(() => {});
	});

	await postmortem.quit(7);
}

async function runCleanupDeadlineFatal(): Promise<void> {
	process.env.GJC_CLEANUP_DEADLINE_MS = "300";
